window.EXAM_BANK = {"meta":{"title":"Thin-Film Solar Cells | Exam Lab","reviewFile":"Solar Cell-Review.pdf","reviewPages":53,"description":"依據使用者提供的 53 頁課程統整講義與歷屆考卷製作。含觀念延伸標記；非教師正式題庫。"},"chapters":["太陽能與能源轉換","光的本質・科學史","光電效應・光子能量","能隙・摻雜","PN 接面・內建電場","矽晶生長・製程","J–V 曲線・效率","EQE・IQE","光學損失・電極","SQ 極限・Tandem","載子復合機制","歷屆考題延伸"],"questions":[{"id":"M001","type":"mc","chapter":1,"difficulty":1,"question":"Which pathway directly converts sunlight into electricity?","options":["Solar thermal heating","Photovoltaic effect","Solar water heating","Combustion"],"answer":1,"explain":"Photovoltaic effect 將光能直接轉換為電能；太陽熱能與熱水系統主要產生熱。","source":"1","sourceKind":"review","pages":[1],"model":"Photovoltaic effect"},{"id":"M002","type":"mc","chapter":1,"difficulty":1,"question":"What is the primary output of a solar thermal collector?","options":["Electric current","Hydrogen gas","Heat for water or space heating","Lithium ions"],"answer":2,"explain":"太陽熱集熱器利用日光產生熱，不是利用 PN 接面直接發電。","source":"1","sourceKind":"review","pages":[1],"model":"Heat for water or space heating"},{"id":"M003","type":"mc","chapter":1,"difficulty":1,"question":"What is the energy input of a conventional solar cell during operation?","options":["Sunlight","Hydrogen and oxygen","A charged electrolyte","Stored chemical fuel"],"answer":0,"explain":"太陽能電池的輸入是光，光照停止時一般也不再持續輸出光生電力。","source":"2","sourceKind":"review","pages":[2],"model":"Sunlight"},{"id":"M004","type":"mc","chapter":1,"difficulty":1,"question":"Which energy device normally needs continuous H₂ and O₂ supply?","options":["Solar cell","Fuel cell","Lithium battery","Capacitor"],"answer":1,"explain":"燃料電池靠持續供應的氫與氧進行電化學反應產電。","source":"2","sourceKind":"review","pages":[2],"model":"Fuel cell"},{"id":"M005","type":"mc","chapter":1,"difficulty":1,"question":"A lithium-ion battery differs from a solar cell because it primarily...","options":["generates photons","stores chemical energy for later use","requires a built-in solar field","uses silicon wafers"],"answer":1,"explain":"電池先儲存化學能再放電；太陽能電池主要是在有光時轉換能量。","source":"2","sourceKind":"review","pages":[2],"model":"stores chemical energy for later use"},{"id":"M006","type":"mc","chapter":1,"difficulty":2,"question":"What are typical outputs of an H₂/O₂ fuel cell?","options":["Light and silicon","Only hydrogen","Electricity, heat, and water","Only stored charge"],"answer":2,"explain":"氫氧燃料電池進行電化學反應，產生電力、熱與水。","source":"2","sourceKind":"review","pages":[2],"model":"Electricity, heat, and water"},{"id":"M007","type":"mc","chapter":1,"difficulty":2,"question":"Which statement correctly compares a solar cell and a battery?","options":["Both are sunlight-to-electricity converters","A battery stores energy; a solar cell converts incoming light","Both need external hydrogen","Solar cells always deliver power in darkness"],"answer":1,"explain":"太陽電池是 energy converter；鋰電池主要是 energy storage device。","source":"2","sourceKind":"review","pages":[2],"model":"A battery stores energy; a solar cell converts incoming light"},{"id":"M008","type":"mc","chapter":1,"difficulty":2,"question":"A shaded solar module with no other energy input normally...","options":["maintains the same photocurrent","produces more voltage","produces no significant photovoltaic power","becomes a fuel cell"],"answer":2,"explain":"缺少入射光就無法持續產生光生載子；實際上仍可能有微弱暗電流或殘餘電能。","source":"2","sourceKind":"review","pages":[2],"model":"produces no significant photovoltaic power"},{"id":"M009","type":"mc","chapter":2,"difficulty":1,"question":"Who argued that light behaves like particles?","options":["Thomas Young","Isaac Newton","Hans Queisser","Edmond Becquerel"],"answer":1,"explain":"牛頓主張光的微粒觀；Thomas Young 以干涉等現象支持波動觀。","source":"4","sourceKind":"review","pages":[4],"model":"Isaac Newton"},{"id":"M010","type":"mc","chapter":2,"difficulty":1,"question":"Who is associated with evidence for the wave nature of light through interference?","options":["Thomas Young","William Shockley","Charles Fritts","Jan Czochralski"],"answer":0,"explain":"楊氏雙狹縫干涉是光具波動性的經典證據。","source":"4","sourceKind":"review","pages":[4],"model":"Thomas Young"},{"id":"M011","type":"mc","chapter":2,"difficulty":1,"question":"Which observation is strong evidence that light behaves as a wave?","options":["Photoelectron emission only","Interference patterns","P-type doping","Auger recombination"],"answer":1,"explain":"干涉與繞射能用光波疊加解釋，是光的波動性關鍵證據。","source":"4","sourceKind":"review","pages":[4],"model":"Interference patterns"},{"id":"M012","type":"mc","chapter":2,"difficulty":1,"question":"Which statement about photons is correct?","options":["A photon has a fixed energy independent of frequency","A photon is an energy packet with E = hν","A photon is an electron","Photon energy depends only on brightness"],"answer":1,"explain":"光子是量子化的能量包，單顆光子能量由頻率 ν 決定。","source":"5","sourceKind":"review","pages":[5],"model":"A photon is an energy packet with E = hν"},{"id":"M013","type":"mc","chapter":2,"difficulty":1,"question":"Which scientist explained the photoelectric effect using light quanta?","options":["Albert Einstein","Thomas Young","William Shockley","Czochralski"],"answer":0,"explain":"Einstein 於 1905 年以光量子理論解釋光電效應。","source":"5-6","sourceKind":"review","pages":[5,6],"model":"Albert Einstein"},{"id":"M014","type":"mc","chapter":2,"difficulty":2,"question":"Einstein received the Nobel Prize in Physics for work especially related to...","options":["the photovoltaic cell patent","the law of the photoelectric effect","the Czochralski process","Auger recombination"],"answer":1,"explain":"愛因斯坦獲 1921 年諾貝爾物理獎，頒獎理由中特別提到光電效應定律。","source":"6","sourceKind":"review","pages":[6],"model":"the law of the photoelectric effect"},{"id":"M015","type":"mc","chapter":2,"difficulty":1,"question":"Who discovered the photovoltaic effect in 1839?","options":["Isaac Newton","Edmond Becquerel","Thomas Young","Albert Einstein"],"answer":1,"explain":"1839 年 Edmond Becquerel 發現光伏效應；原期中考第 1 題也考過。","source":"歷屆Q1","sourceKind":"past-exam","sourceNote":"此題源自你提供的歷屆考卷或延伸史實；53 頁統整講義未直接收錄該資訊。","pages":[],"model":"Edmond Becquerel"},{"id":"M016","type":"mc","chapter":2,"difficulty":2,"question":"Which scientist made an early selenium-based solar cell in 1883?","options":["Charles Fritts","Hans Queisser","Thomas Young","William Shockley"],"answer":0,"explain":"Charles Fritts 於 1883 年製作早期硒太陽能電池，是歷史延伸記憶題。","source":"歷屆延伸","sourceKind":"past-exam","sourceNote":"此題源自你提供的歷屆考卷或延伸史實；53 頁統整講義未直接收錄該資訊。","pages":[],"model":"Charles Fritts"},{"id":"M017","type":"mc","chapter":2,"difficulty":2,"question":"Who developed the detailed-balance limit of ideal single-junction solar cells in 1961?","options":["Newton and Young","Becquerel and Einstein","Shockley and Queisser","Fritts and Czochralski"],"answer":2,"explain":"Shockley–Queisser 極限於 1961 年提出，是單接面理想電池的效率上限模型。","source":"47","sourceKind":"review","pages":[47],"model":"Shockley and Queisser"},{"id":"M018","type":"mc","chapter":2,"difficulty":2,"question":"Which historical sequence is chronological?","options":["Einstein 1905 → Becquerel 1839 → SQ 1961","Becquerel 1839 → Fritts 1883 → Einstein 1905 → SQ 1961","SQ 1961 → Young → Einstein 1905","Fritts 1883 → Becquerel 1839 → Einstein 1905"],"answer":1,"explain":"常見考法是排序：1839 光伏發現 → 1883 早期硒電池 → 1905 光量子 → 1961 SQ 極限。","source":"4-6,47","sourceKind":"review","pages":[4,5,6,47],"model":"Becquerel 1839 → Fritts 1883 → Einstein 1905 → SQ 1961"},{"id":"M019","type":"mc","chapter":2,"difficulty":2,"question":"Which phenomenon is most closely related to Thomas Young?","options":["Interference","Phosphorus diffusion","Thermalization","ITO conduction"],"answer":0,"explain":"Thomas Young 與雙狹縫干涉關聯最直接。","source":"4","sourceKind":"review","pages":[4],"model":"Interference"},{"id":"M020","type":"mc","chapter":3,"difficulty":1,"question":"What is the equation for photon energy?","options":["E = h/ν","E = hν = hc/λ","E = λ/h","E = q/λ"],"answer":1,"explain":"能量與頻率正比，與波長反比：E=hν=hc/λ。","source":"5,10","sourceKind":"review","pages":[5,10],"model":"E = hν = hc/λ"},{"id":"M021","type":"mc","chapter":3,"difficulty":1,"question":"If the wavelength is halved, the photon energy...","options":["is halved","stays constant","doubles","becomes zero"],"answer":2,"explain":"E = hc/λ，波長減半代表單顆光子能量加倍。","source":"10","sourceKind":"review","pages":[10],"model":"doubles"},{"id":"M022","type":"mc","chapter":3,"difficulty":1,"question":"For photon energy in eV and wavelength in nm, which approximation is correct?","options":["E = 1240 × λ","E = 1240 / λ","E = λ / 1240","E = 1240 + λ"],"answer":1,"explain":"課堂常用公式 E(eV) ≈ 1240/λ(nm)。","source":"10","sourceKind":"review","pages":[10],"model":"E = 1240 / λ"},{"id":"M023","type":"mc","chapter":3,"difficulty":1,"question":"What is the unit of Planck's constant h?","options":["J·s","J/s","nm","C/m"],"answer":0,"explain":"Planck constant 的 SI 單位是 J·s，因為 E = hν。","source":"10","sourceKind":"review","pages":[10],"model":"J·s"},{"id":"M024","type":"mc","chapter":3,"difficulty":2,"question":"Which photon has higher energy?","options":["900 nm","700 nm","400 nm","1200 nm"],"answer":2,"explain":"波長越短能量越高；400 nm 比其他選項能量高。","source":"10","sourceKind":"review","pages":[10],"model":"400 nm"},{"id":"M025","type":"mc","chapter":3,"difficulty":2,"question":"What happens to photon energy if intensity increases at a fixed wavelength?","options":["It increases","It decreases","It remains the same","It becomes work function"],"answer":2,"explain":"固定波長下，每顆光子能量不變；照度提高通常代表光子數增加。","source":"12-13","sourceKind":"review","pages":[12,13],"model":"It remains the same"},{"id":"M026","type":"mc","chapter":3,"difficulty":2,"question":"What does brighter monochromatic light mainly increase?","options":["Energy per photon","Number of photons arriving per second","Work function","Bandgap"],"answer":1,"explain":"提高相同波長光束的強度會增加光子通量，不會改變單顆光子的 E。","source":"12","sourceKind":"review","pages":[12],"model":"Number of photons arriving per second"},{"id":"M027","type":"mc","chapter":3,"difficulty":1,"question":"For a metal, what is the work function Φ?","options":["The optical bandgap","Minimum energy to move an electron from metal to vacuum","The open-circuit voltage","The current density"],"answer":1,"explain":"功函數指電子由材料的費米能階到真空能階所需的最小能量。","source":"8","sourceKind":"review","pages":[8],"model":"Minimum energy to move an electron from metal to vacuum"},{"id":"M028","type":"mc","chapter":3,"difficulty":2,"question":"Which condition is required for external photoelectron emission?","options":["hν < Φ","hν ≥ Φ","λ must be infrared","Light must be very bright"],"answer":1,"explain":"外部光電效應的門檻為光子能量至少等於功函數。","source":"8","sourceKind":"review","pages":[8],"model":"hν ≥ Φ"},{"id":"M029","type":"mc","chapter":3,"difficulty":1,"question":"How is the maximum kinetic energy of photoelectrons written?","options":["Kmax = Φ − hν","Kmax = hν + Φ","Kmax = hν − Φ","Kmax = qVoc"],"answer":2,"explain":"逸出後的最大動能 Kmax=hν−Φ（忽略其他損失）。","source":"8","sourceKind":"review","pages":[8],"model":"Kmax = hν − Φ"},{"id":"M030","type":"mc","chapter":3,"difficulty":2,"question":"A zinc plate does not discharge under intense visible light because...","options":["visible light has no photons","each photon is below the emission threshold","the plate is a battery","the photons move too slowly"],"answer":1,"explain":"再亮的低頻光，只要單顆光子能量低於逸出門檻，就無法以單光子光電效應讓電子逸出。","source":"11-14","sourceKind":"review","pages":[11,12,13,14],"model":"each photon is below the emission threshold"},{"id":"M031","type":"mc","chapter":3,"difficulty":2,"question":"What change can cause zinc photoemission if the first light is below threshold?","options":["Increase the plate area","Use shorter-wavelength UV light","Only increase brightness","Change light polarization only"],"answer":1,"explain":"提高頻率、縮短波長可以使光子能量超過門檻。","source":"14","sourceKind":"review","pages":[14],"model":"Use shorter-wavelength UV light"},{"id":"M032","type":"mc","chapter":3,"difficulty":1,"question":"In the external photoelectric effect, excited electrons...","options":["must remain in the crystal","leave the material surface","always form excitons","only travel through a p–n junction"],"answer":1,"explain":"講義比較重點：外部 photoelectric 電子逸出材料；photovoltaic 透過內部載子分離產電。","source":"7","sourceKind":"review","pages":[7],"model":"leave the material surface"},{"id":"M033","type":"mc","chapter":3,"difficulty":2,"question":"Which statement about the photovoltaic effect is correct?","options":["Electrons must escape into vacuum","Light-generated carriers are separated and collected","Only metals exhibit it","It requires UV photons above a metal work function"],"answer":1,"explain":"光伏效應主要靠材料內光生載子分離、收集並建立端電壓，無須逸出真空。","source":"7","sourceKind":"review","pages":[7],"model":"Light-generated carriers are separated and collected"},{"id":"M034","type":"mc","chapter":3,"difficulty":2,"question":"A 620-nm photon has energy closest to...","options":["0.50 eV","1.00 eV","2.00 eV","4.00 eV"],"answer":2,"explain":"E=1240/620=2.00 eV。","source":"10","sourceKind":"review","pages":[10],"model":"2.00 eV"},{"id":"M035","type":"mc","chapter":3,"difficulty":2,"question":"What is the threshold wavelength for a 3.0-eV work function?","options":["1240 nm","827 nm","620 nm","413 nm"],"answer":3,"explain":"λmax=1240/3.0=413.3 nm，波長需不大於門檻。","source":"歷屆Q2","sourceKind":"past-exam","sourceNote":"此題源自你提供的歷屆考卷或延伸史實；53 頁統整講義未直接收錄該資訊。","pages":[],"model":"413 nm"},{"id":"M036","type":"mc","chapter":3,"difficulty":3,"question":"Light of 500 nm strikes a metal with Φ = 3.0 eV. What happens?","options":["Electrons escape with 0.52 eV","Electrons cannot escape by single-photon absorption","Electrons escape with 3.0 eV","Kmax = 5.48 eV"],"answer":1,"explain":"500 nm 光子能量 2.48 eV，低於 Φ=3.0 eV，因此無外部單光子光電子逸出。","source":"8-10","sourceKind":"review","pages":[8,9,10],"model":"Electrons cannot escape by single-photon absorption"},{"id":"M037","type":"mc","chapter":3,"difficulty":3,"question":"A 310-nm photon reaches a metal with Φ=3.0 eV. Its maximum photoelectron kinetic energy is...","options":["1.0 eV","3.0 eV","4.0 eV","7.0 eV"],"answer":0,"explain":"E=1240/310=4.0 eV；Kmax=4.0−3.0=1.0 eV。","source":"8-10","sourceKind":"review","pages":[8,9,10],"model":"1.0 eV"},{"id":"M038","type":"mc","chapter":4,"difficulty":1,"question":"What does Eg represent in a semiconductor?","options":["Work function to vacuum","Energy separation between valence and conduction bands","Amount of incident light","Fill factor"],"answer":1,"explain":"能隙 Eg 是價帶頂與導帶底的能量差，不等於金屬功函數。","source":"16","sourceKind":"review","pages":[16],"model":"Energy separation between valence and conduction bands"},{"id":"M039","type":"mc","chapter":4,"difficulty":1,"question":"A photon can excite a valence electron across the bandgap when...","options":["E < Eg","E ≥ Eg","intensity is zero","frequency is zero"],"answer":1,"explain":"在簡化單光子吸收模型下，光子能量至少等於 Eg 才可能形成帶間激發。","source":"16-17","sourceKind":"review","pages":[16,17],"model":"E ≥ Eg"},{"id":"M040","type":"mc","chapter":4,"difficulty":1,"question":"Which material class generally has a large bandgap?","options":["Metal","Conductor","Insulator","Heavily doped semiconductor"],"answer":2,"explain":"絕緣體一般具有寬能隙，而導體沒有典型半導體的禁帶。","source":"16","sourceKind":"review","pages":[16],"model":"Insulator"},{"id":"M041","type":"mc","chapter":4,"difficulty":2,"question":"For Eg = 1.5 eV, which wavelengths can generate band-to-band excitation?","options":["Only λ > 827 nm","Only exactly 827 nm","λ ≤ approximately 827 nm","Any λ if bright enough"],"answer":2,"explain":"λg=1240/1.5≈827 nm；短於截止波長的光子能量較高。","source":"17","sourceKind":"review","pages":[17],"model":"λ ≤ approximately 827 nm"},{"id":"M042","type":"mc","chapter":4,"difficulty":2,"question":"For a semiconductor with Eg = 2 eV, which light is below the absorption threshold?","options":["500 nm","600 nm","700 nm","400 nm"],"answer":2,"explain":"λg=620 nm；700 nm 光子只有 1.77 eV，小於 2 eV。","source":"16-17","sourceKind":"review","pages":[16,17],"model":"700 nm"},{"id":"M043","type":"mc","chapter":4,"difficulty":1,"question":"What type of dopant is phosphorus in silicon?","options":["Acceptor","Donor","Intrinsic carrier","Insulating impurity"],"answer":1,"explain":"P 有 5 個價電子，對 Si 提供額外電子，為 donor。","source":"20","sourceKind":"review","pages":[20],"model":"Donor"},{"id":"M044","type":"mc","chapter":4,"difficulty":1,"question":"What type of dopant is boron in silicon?","options":["Donor","Acceptor","Metallic conductor","Photon absorber only"],"answer":1,"explain":"B 有 3 個價電子，容易產生電洞，為 acceptor。","source":"20","sourceKind":"review","pages":[20],"model":"Acceptor"},{"id":"M045","type":"mc","chapter":4,"difficulty":1,"question":"What is the majority carrier in n-type silicon?","options":["Hole","Photon","Electron","Phonon"],"answer":2,"explain":"N-type 的多數載子是電子。","source":"20","sourceKind":"review","pages":[20],"model":"Electron"},{"id":"M046","type":"mc","chapter":4,"difficulty":1,"question":"What is the majority carrier in p-type silicon?","options":["Hole","Electron","Ionized donor","Photon"],"answer":0,"explain":"P-type 的多數載子是電洞。","source":"20","sourceKind":"review","pages":[20],"model":"Hole"},{"id":"M047","type":"mc","chapter":4,"difficulty":2,"question":"Which dopant typically produces p-type Si?","options":["Phosphorus","Arsenic","Boron","Antimony"],"answer":2,"explain":"硼是第 III 族，取代 Si 後為受體，增加電洞濃度。","source":"20","sourceKind":"review","pages":[20],"model":"Boron"},{"id":"M048","type":"mc","chapter":4,"difficulty":2,"question":"How many valence electrons does phosphorus have?","options":["Three","Four","Five","Six"],"answer":2,"explain":"磷為第 V 族，有 5 個價電子；多出的一個較易成為自由電子。","source":"20","sourceKind":"review","pages":[20],"model":"Five"},{"id":"M049","type":"mc","chapter":4,"difficulty":2,"question":"Which term describes doping with no intentional donors or acceptors?","options":["Degenerate","Intrinsic","N-type","P-type"],"answer":1,"explain":"Intrinsic semiconductor 指本徵半導體，與摻雜型外因半導體相對。","source":"20","sourceKind":"review","pages":[20],"model":"Intrinsic"},{"id":"M050","type":"mc","chapter":4,"difficulty":3,"question":"Why can heavily doped ITO be both transparent and conductive in visible light?","options":["It has no electrons","Wide optical gap and high free-carrier concentration","It is pure metal with zero gap","It works only under UV light"],"answer":1,"explain":"ITO 是透明導電氧化物，具有可見光高透過與高自由載子濃度。","source":"歷屆Q6","sourceKind":"past-exam","sourceNote":"此題源自你提供的歷屆考卷或延伸史實；53 頁統整講義未直接收錄該資訊。","pages":[],"model":"Wide optical gap and high free-carrier concentration"},{"id":"M051","type":"mc","chapter":5,"difficulty":1,"question":"In a p–n junction, electrons initially diffuse from...","options":["P to N","N to P","Both to vacuum","Metal to insulator"],"answer":1,"explain":"N 側電子濃度高，因此電子擴散由 N 向 P。","source":"25","sourceKind":"review","pages":[25],"model":"N to P"},{"id":"M052","type":"mc","chapter":5,"difficulty":1,"question":"In a p–n junction, holes initially diffuse from...","options":["N to P","P to N","P to vacuum","N to metal"],"answer":1,"explain":"P 側電洞濃度高，電洞擴散由 P 向 N。","source":"25","sourceKind":"review","pages":[25],"model":"P to N"},{"id":"M053","type":"mc","chapter":5,"difficulty":2,"question":"What remains on the N side of a depletion region after electrons diffuse away?","options":["Mobile holes only","Fixed positively charged donor ions","Fixed negatively charged acceptors","Photons"],"answer":1,"explain":"N 側捐贈電子離開後留下不可移動的正 donor ions。","source":"26","sourceKind":"review","pages":[26],"model":"Fixed positively charged donor ions"},{"id":"M054","type":"mc","chapter":5,"difficulty":2,"question":"What remains on the P side of a depletion region?","options":["Fixed positive donor ions","Free electrons","Fixed negative acceptor ions","Neutral light particles"],"answer":2,"explain":"P 側電洞消失後留下固定的負 acceptor ions。","source":"26","sourceKind":"review","pages":[26],"model":"Fixed negative acceptor ions"},{"id":"M055","type":"mc","chapter":5,"difficulty":1,"question":"What creates the built-in electric field at an ideal p–n junction?","options":["Contact shading","Separated fixed ionized dopants","Only incident sunlight","An external battery is always necessary"],"answer":1,"explain":"空乏區內的固定離子化摻雜原子造成空間電荷及內建電場。","source":"26","sourceKind":"review","pages":[26],"model":"Separated fixed ionized dopants"},{"id":"M056","type":"mc","chapter":5,"difficulty":2,"question":"The built-in electric field direction is from...","options":["P side to N side","N side to P side","Vacuum to metal","Always upward in the drawing"],"answer":1,"explain":"電場由正固定離子 N 側指向負固定離子 P 側。","source":"26","sourceKind":"review","pages":[26],"model":"N side to P side"},{"id":"M057","type":"mc","chapter":5,"difficulty":2,"question":"Under the built-in field, an electron is driven toward...","options":["P side","N side","the center forever","the vacuum level"],"answer":1,"explain":"電子帶負電，受力方向與電場相反，故向 N 側漂移。","source":"26","sourceKind":"review","pages":[26],"model":"N side"},{"id":"M058","type":"mc","chapter":5,"difficulty":2,"question":"Under the built-in field, a hole is driven toward...","options":["N side","P side","vacuum","the rear grid only"],"answer":1,"explain":"電洞帶正電，受力沿電場方向，向 P 側移動。","source":"26","sourceKind":"review","pages":[26],"model":"P side"},{"id":"M059","type":"mc","chapter":5,"difficulty":2,"question":"Why is the depletion region named 'depletion'?","options":["It contains no atoms","It has relatively few mobile majority carriers","It is completely empty of electric field","It removes the bandgap"],"answer":1,"explain":"空乏區的自由多數載子明顯減少，但仍有固定離子與電場。","source":"26","sourceKind":"review","pages":[26],"model":"It has relatively few mobile majority carriers"},{"id":"M060","type":"mc","chapter":5,"difficulty":2,"question":"What is the purpose of the junction field in a solar cell?","options":["To create light without input","To help separate photogenerated electron–hole pairs","To increase metal reflection","To stop all diffusion permanently"],"answer":1,"explain":"電場幫助光生電子電洞分離並導向適當區域收集。","source":"28","sourceKind":"review","pages":[28],"model":"To help separate photogenerated electron–hole pairs"},{"id":"M061","type":"mc","chapter":5,"difficulty":3,"question":"At thermal equilibrium in a p–n junction, which statement is most accurate?","options":["Diffusion is zero but drift is nonzero","Drift and diffusion currents balance","No built-in field exists","A continuous net current flows in the dark"],"answer":1,"explain":"平衡狀態下有擴散及漂移成分，但總電流互相抵消。","source":"25-26 延伸","sourceKind":"extension","sourceNote":"對應講義主題的延伸觀念；細節不一定逐字出現在講義。","pages":[25,26],"model":"Drift and diffusion currents balance"},{"id":"M062","type":"mc","chapter":5,"difficulty":3,"question":"Is all useful photogeneration confined to the depletion region?","options":["Yes, elsewhere no photons are absorbed","No, minority carriers generated nearby can also diffuse to the junction","Yes, silicon absorbs only inside it","No, all carriers must escape to vacuum"],"answer":1,"explain":"中性區的光生少數載子可透過擴散到達接面而被收集，並不限於空乏區內。","source":"28 延伸","sourceKind":"extension","sourceNote":"對應講義主題的延伸觀念；細節不一定逐字出現在講義。","pages":[28],"model":"No, minority carriers generated nearby can also diffuse to the junction"},{"id":"M063","type":"mc","chapter":6,"difficulty":1,"question":"Which method grows a single-crystal silicon ingot by pulling a seed from molten Si?","options":["Czochralski growth","Spin coating","Screen printing","Electroplating"],"answer":0,"explain":"Czochralski（CZ）法使用單晶種晶接觸矽熔液，旋轉並向上拉出晶棒。","source":"30","sourceKind":"review","pages":[30],"model":"Czochralski growth"},{"id":"M064","type":"mc","chapter":6,"difficulty":2,"question":"What determines the crystal orientation of the grown Czochralski ingot?","options":["Anti-reflection coating","Single-crystal seed","Front grid width","Solar spectrum"],"answer":1,"explain":"Seed crystal 的晶向決定後續成長單晶晶棒的晶向。","source":"30","sourceKind":"review","pages":[30],"model":"Single-crystal seed"},{"id":"M065","type":"mc","chapter":6,"difficulty":1,"question":"After growth, the silicon ingot is typically...","options":["dissolved into water","sliced into wafers","used as a transparent electrode","turned directly into a fuel cell"],"answer":1,"explain":"矽單晶棒需要切成晶圓 wafer 才能進一步製作太陽能電池。","source":"30","sourceKind":"review","pages":[30],"model":"sliced into wafers"},{"id":"M066","type":"mc","chapter":6,"difficulty":2,"question":"What is the main purpose of surface texturing on a silicon solar cell?","options":["Increase optical reflection","Reduce reflection and trap more incident light","Remove all dopants","Eliminate the rear electrode"],"answer":1,"explain":"表面微結構讓入射光有較多次機會進入材料，降低反射損失。","source":"32","sourceKind":"review","pages":[32],"model":"Reduce reflection and trap more incident light"},{"id":"M067","type":"mc","chapter":6,"difficulty":1,"question":"What does ARC stand for?","options":["Active Recombination Contact","Anti-Reflection Coating","Auger Rate Constant","Atomic Rear Collector"],"answer":1,"explain":"ARC 是 anti-reflection coating，降低前表面反射。","source":"32","sourceKind":"review","pages":[32],"model":"Anti-Reflection Coating"},{"id":"M068","type":"mc","chapter":6,"difficulty":2,"question":"What is a common ARC material deposited by PECVD on silicon solar cells?","options":["SiNx","Pure gold","NaCl","Metallic Al only"],"answer":0,"explain":"講義指出 SiNx 抗反射層以 PECVD 沉積在電極印刷之前。","source":"31","sourceKind":"review","pages":[31],"model":"SiNx"},{"id":"M069","type":"mc","chapter":6,"difficulty":2,"question":"What does PSG stand for in silicon solar-cell processing?","options":["Phosphosilicate Glass","Photon Solar Grid","Plasma Silicon Growth","Polymer Surface Gel"],"answer":0,"explain":"磷擴散會形成 phosphosilicate glass，製程中需要去除。","source":"31","sourceKind":"review","pages":[31],"model":"Phosphosilicate Glass"},{"id":"M070","type":"mc","chapter":6,"difficulty":2,"question":"Which step creates an n-type emitter on a p-type silicon wafer in a classic process?","options":["Phosphorus diffusion","Removing ARC","Testing and sorting","Adding boron-free water"],"answer":0,"explain":"磷擴散將近表面矽摻成 N 型，形成 PN junction。","source":"31","sourceKind":"review","pages":[31],"model":"Phosphorus diffusion"},{"id":"M071","type":"mc","chapter":6,"difficulty":2,"question":"Why are unwanted rear and edge junctions removed?","options":["To prevent shunts or unwanted electrical paths","To increase top shading","To eliminate all light absorption","To form the seed crystal"],"answer":0,"explain":"去除背面及邊緣非預期的接面，可減少漏電或短路路徑。","source":"31","sourceKind":"review","pages":[31],"model":"To prevent shunts or unwanted electrical paths"},{"id":"M072","type":"mc","chapter":6,"difficulty":2,"question":"What is the purpose of firing after electrode printing?","options":["Grow the initial Si ingot","Form good electrical contacts through the dielectric","Change photons into holes in air","Make Si an insulator"],"answer":1,"explain":"印刷電極後 firing 可幫助金屬接觸穿透或接觸介電層並形成低阻接觸。","source":"31","sourceKind":"review","pages":[31],"model":"Form good electrical contacts through the dielectric"},{"id":"M073","type":"mc","chapter":6,"difficulty":2,"question":"Which step normally comes after cell fabrication for quality control?","options":["Test and sort","Seed crystal insertion","Only grow another ingot","Remove every electrode"],"answer":0,"explain":"製程圖最後包括 test & sort，依元件表現進行測試與分級。","source":"31","sourceKind":"review","pages":[31],"model":"Test and sort"},{"id":"M074","type":"mc","chapter":6,"difficulty":3,"question":"What is the key benefit of combining pyramidal texturing and ARC?","options":["Higher reflection than planar Si","Lower front-surface reflection than bare planar Si","Zero Auger recombination","No need for contacts"],"answer":1,"explain":"講義圖比較 bare planar、planar+ARC、textured+ARC，後者通常能顯著減反。","source":"32","sourceKind":"review","pages":[32],"model":"Lower front-surface reflection than bare planar Si"},{"id":"M075","type":"mc","chapter":6,"difficulty":3,"question":"Which order is reasonable for a classic Si cell process?","options":["Print → melt Si → cut wafer → diffuse P","Wafer → texture → phosphorus diffusion → PSG removal → ARC → metallization","ARC → CZ pull → test → wafer slice","Test first → print → grow crystal"],"answer":1,"explain":"講義重點為晶圓、表面粗化、磷擴散、去 PSG、ARC、電極印刷與燒成、測試。","source":"30-31","sourceKind":"review","pages":[30,31],"model":"Wafer → texture → phosphorus diffusion → PSG removal → ARC → metallization"},{"id":"M076","type":"mc","chapter":7,"difficulty":1,"question":"What is Voc?","options":["Voltage when external current is zero","Voltage when light intensity is zero","Current when voltage is zero","The bandgap in eV"],"answer":0,"explain":"開路電壓 Voc 是外電流 I=0 時的端電壓。","source":"34","sourceKind":"review","pages":[34],"model":"Voltage when external current is zero"},{"id":"M077","type":"mc","chapter":7,"difficulty":1,"question":"What is Isc?","options":["Current at an external voltage of zero","Current at open circuit","Voltage at maximum power","Quantum efficiency"],"answer":0,"explain":"短路電流 Isc 是外部端電壓 V=0 時的電流。","source":"35","sourceKind":"review","pages":[35],"model":"Current at an external voltage of zero"},{"id":"M078","type":"mc","chapter":7,"difficulty":2,"question":"At open circuit, the external current is...","options":["Maximum","Zero","Always negative infinity","Equal to incoming photon flux"],"answer":1,"explain":"開路沒有外部閉合通路，因此外電流為零，端點達 Voc。","source":"34","sourceKind":"review","pages":[34],"model":"Zero"},{"id":"M079","type":"mc","chapter":7,"difficulty":2,"question":"At short circuit, the terminal voltage is ideally...","options":["Voc","Eg/q","Zero","Infinite"],"answer":2,"explain":"短路狀態兩端被接線直接連接，端電壓為 0。","source":"35","sourceKind":"review","pages":[35],"model":"Zero"},{"id":"M080","type":"mc","chapter":7,"difficulty":1,"question":"What is the maximum power point (MPP)?","options":["Point where both V and I are zero","Operating point with the largest product V × I","Always the Voc point","Always the Isc point"],"answer":1,"explain":"MPP 為 I–V 曲線上最大功率輸出點，P=V×I。","source":"36","sourceKind":"review","pages":[36],"model":"Operating point with the largest product V × I"},{"id":"M081","type":"mc","chapter":7,"difficulty":1,"question":"Which expression gives solar-cell PCE?","options":["Voc + Jsc + FF","Voc × Jsc × FF / Pin","Pin / Voc","IQE / EQE"],"answer":1,"explain":"PCE=Pmax/Pin，最大功率密度=Voc×Jsc×FF。","source":"37","sourceKind":"review","pages":[37],"model":"Voc × Jsc × FF / Pin"},{"id":"M082","type":"mc","chapter":7,"difficulty":1,"question":"What does FF stand for?","options":["Photon fill fraction","Fill factor","Fermi frequency","Front field"],"answer":1,"explain":"FF = Fill Factor，反映 J–V 曲線的方正程度與最大功率比例。","source":"37","sourceKind":"review","pages":[37],"model":"Fill factor"},{"id":"M083","type":"mc","chapter":7,"difficulty":2,"question":"What is the correct definition of FF?","options":["Pmax / (Voc × Isc)","Voc / Isc","Jsc × Pin","EQE / IQE"],"answer":0,"explain":"填充因子 FF=Pmax/(Voc×Isc)，用電流密度也等價。","source":"37","sourceKind":"review","pages":[37],"model":"Pmax / (Voc × Isc)"},{"id":"M084","type":"mc","chapter":7,"difficulty":2,"question":"Under AM1.5G one-sun conditions, standard incident power is about...","options":["1 mW/cm²","10 mW/cm²","100 mW/cm²","1000 W/cm²"],"answer":2,"explain":"講義採 AM1.5G 1 sun = 100 mW/cm²。","source":"37","sourceKind":"review","pages":[37],"model":"100 mW/cm²"},{"id":"M085","type":"mc","chapter":7,"difficulty":2,"question":"A cell has Jsc = 20 mA/cm², Voc = 1.0 V, FF = 0.75. Its PCE is...","options":["1.5%","15%","20%","75%"],"answer":1,"explain":"在 Pin=100 mW/cm² 下，PCE(%)=20×1.0×0.75=15%。","source":"37","sourceKind":"review","pages":[37],"model":"15%"},{"id":"M086","type":"mc","chapter":7,"difficulty":2,"question":"Keeping Voc and Jsc fixed, raising FF from 0.70 to 0.77 changes PCE by...","options":["10% relative increase","70% relative increase","7 percentage points always","No change"],"answer":0,"explain":"效率正比 FF，0.77/0.70=1.10，因此相對增加 10%。","source":"37","sourceKind":"review","pages":[37],"model":"10% relative increase"},{"id":"M087","type":"mc","chapter":7,"difficulty":2,"question":"Which change usually decreases Voc?","options":["Lower recombination","More recombination","Increasing optical absorption alone","Reducing shading alone"],"answer":1,"explain":"復合增強通常讓暗飽和電流增加、準費米能階分裂降低，Voc 下降。","source":"歷屆Q4","sourceKind":"past-exam","sourceNote":"此題源自你提供的歷屆考卷或延伸史實；53 頁統整講義未直接收錄該資訊。","pages":[],"model":"More recombination"},{"id":"M088","type":"mc","chapter":7,"difficulty":3,"question":"Which parameter is a current density instead of a total current?","options":["Isc (A)","Jsc (mA/cm²)","Voc (V)","FF (unitless)"],"answer":1,"explain":"Jsc 是每單位面積的短路電流密度，Isc 是總電流。","source":"37","sourceKind":"review","pages":[37],"model":"Jsc (mA/cm²)"},{"id":"M089","type":"mc","chapter":7,"difficulty":3,"question":"In a practical solar cell, how does output power behave at Voc?","options":["It reaches maximum","It is zero because I = 0","It equals Pin","It equals Jsc"],"answer":1,"explain":"P=I×V，開路 I=0，因此輸出功率為零。","source":"34-36","sourceKind":"review","pages":[34,35,36],"model":"It is zero because I = 0"},{"id":"M090","type":"mc","chapter":7,"difficulty":3,"question":"In a practical solar cell, how does output power behave at Isc?","options":["It is zero because V = 0","It is maximum","It equals Voc","It is negative infinity"],"answer":0,"explain":"短路時端電壓 V=0，因此輸出功率為零。","source":"34-36","sourceKind":"review","pages":[34,35,36],"model":"It is zero because V = 0"},{"id":"M091","type":"mc","chapter":8,"difficulty":1,"question":"EQE is the ratio of collected carriers to...","options":["incident photons","absorbed photons only","reflected photons","generated holes only"],"answer":0,"explain":"EQE（或 IPCE）=收集電子數／入射光子數。","source":"40","sourceKind":"review","pages":[40],"model":"incident photons"},{"id":"M092","type":"mc","chapter":8,"difficulty":1,"question":"IQE is the ratio of collected carriers to...","options":["incident photons","absorbed photons","incoming heat","external resistance"],"answer":1,"explain":"IQE=收集電子數／被吸收光子數。","source":"40","sourceKind":"review","pages":[40],"model":"absorbed photons"},{"id":"M093","type":"mc","chapter":8,"difficulty":1,"question":"What does IPCE stand for?","options":["Incident Photon-to-Current Efficiency","Internal Photon Charge Energy","Integrated Power Conversion Estimate","Initial Photovoltaic Collection Effect"],"answer":0,"explain":"IPCE 為 incident photon-to-current conversion efficiency，課堂與 EQE 並用。","source":"39-40","sourceKind":"review","pages":[39,40],"model":"Incident Photon-to-Current Efficiency"},{"id":"M094","type":"mc","chapter":8,"difficulty":2,"question":"Which efficiency is usually greater, EQE or IQE?","options":["EQE is always greater","IQE is usually equal to or greater than EQE","They are always opposite signs","Neither can be measured"],"answer":1,"explain":"IQE 分母只計真正被吸收的光子，通常 IQE≥EQE。","source":"40","sourceKind":"review","pages":[40],"model":"IQE is usually equal to or greater than EQE"},{"id":"M095","type":"mc","chapter":8,"difficulty":2,"question":"For absorptance A = 1 − R − T, what is the relationship?","options":["IQE = EQE × A","IQE = EQE / A","EQE = IQE / A","IQE = EQE + A"],"answer":1,"explain":"講義使用 IQE=EQE/(1−R−T)，假設反射、透射與吸收定義一致且忽略寄生吸收影響。","source":"40","sourceKind":"review","pages":[40],"model":"IQE = EQE / A"},{"id":"M096","type":"mc","chapter":8,"difficulty":2,"question":"If EQE=72% and absorptance=90%, IQE is...","options":["64.8%","72%","80%","90%"],"answer":2,"explain":"IQE=0.72/0.90=0.80=80%。","source":"40","sourceKind":"review","pages":[40],"model":"80%"},{"id":"M097","type":"mc","chapter":8,"difficulty":2,"question":"Which factor reduces EQE but does not necessarily reduce intrinsic carrier collection?","options":["Front-grid shading","Longer carrier lifetime","Better passivation","Improved collection field"],"answer":0,"explain":"前電極遮光會減少進入吸收層的光子，造成外量子效率下降。","source":"41,45","sourceKind":"review","pages":[41,45],"model":"Front-grid shading"},{"id":"M098","type":"mc","chapter":8,"difficulty":2,"question":"If a device collects 80 electrons per 100 incident photons, its EQE is...","options":["20%","80%","100%","125%"],"answer":1,"explain":"EQE=80/100=80%。","source":"40","sourceKind":"review","pages":[40],"model":"80%"},{"id":"M099","type":"mc","chapter":8,"difficulty":3,"question":"Which formula links EQE, current, light power, and photon energy?","options":["EQE = (I/q) / (Plight/Ephoton)","EQE = I × q × Plight","EQE = Ephoton/Pin only","EQE = Voc × FF"],"answer":0,"explain":"收集電子速率 I/q，入射光子速率 P_light/E_photon，兩者相除即 EQE。","source":"40","sourceKind":"review","pages":[40],"model":"EQE = (I/q) / (Plight/Ephoton)"},{"id":"M100","type":"mc","chapter":8,"difficulty":3,"question":"If R=10% and T=20%, the device absorptance is...","options":["10%","30%","70%","130%"],"answer":2,"explain":"A=1−R−T=1−0.10−0.20=0.70。","source":"40","sourceKind":"review","pages":[40],"model":"70%"},{"id":"M101","type":"mc","chapter":8,"difficulty":3,"question":"In general, what does low EQE at short wavelengths often indicate in silicon cells?","options":["Front-surface recombination losses","Perfect blue response","Only Auger at the back contact","Higher Si bandgap at front"],"answer":0,"explain":"短波光在表層吸收較多，表面缺陷復合造成 blue loss。","source":"44","sourceKind":"review","pages":[44],"model":"Front-surface recombination losses"},{"id":"M102","type":"mc","chapter":9,"difficulty":1,"question":"Why should a top metal grid cover only a small area?","options":["To maximize shading","To allow light to enter while collecting carriers","Because metal has no resistance","To eliminate the p–n junction"],"answer":1,"explain":"頂部細柵線需要兼顧導電與讓光進入，覆蓋過多會造成 shading。","source":"45","sourceKind":"review","pages":[45],"model":"To allow light to enter while collecting carriers"},{"id":"M103","type":"mc","chapter":9,"difficulty":2,"question":"What is front-grid shading loss?","options":["Current lost due to contact metal blocking light","A lower bandgap caused by metal","Thermalization of hot electrons","Transmission through the rear glass"],"answer":0,"explain":"上電極遮住入射光，光子到不了吸收區，降低 EQE / Jsc。","source":"44-45","sourceKind":"review","pages":[44,45],"model":"Current lost due to contact metal blocking light"},{"id":"M104","type":"mc","chapter":9,"difficulty":2,"question":"Which treatment primarily reduces front-surface reflection?","options":["Thicker full-metal top electrode","Texturing and anti-reflection coating","Extra defect traps","Reducing photon energy"],"answer":1,"explain":"表面紋理與抗反射層可降低光被前表面反射回去的比例。","source":"32","sourceKind":"review","pages":[32],"model":"Texturing and anti-reflection coating"},{"id":"M105","type":"mc","chapter":9,"difficulty":2,"question":"What is meant by 'blue loss' in a silicon EQE breakdown?","options":["Short-wavelength carriers recombine near the front surface","All blue light is transmitted through the cell","Long-wave photons reflect from the rear","The ITO has a blue color"],"answer":0,"explain":"短波長高能光在前表面附近吸收，生成載子若在表面復合就形成 blue loss。","source":"44","sourceKind":"review","pages":[44],"model":"Short-wavelength carriers recombine near the front surface"},{"id":"M106","type":"mc","chapter":9,"difficulty":2,"question":"What contributes to long-wavelength EQE loss?","options":["Front blue recombination only","Incomplete absorption and base-collection losses","Only a larger photon energy","Increased UV emission"],"answer":1,"explain":"長波光子較難被吸收或在較深區域生成載子，與基底收集、寄生吸收有關。","source":"44","sourceKind":"review","pages":[44],"model":"Incomplete absorption and base-collection losses"},{"id":"M107","type":"mc","chapter":9,"difficulty":2,"question":"Which structure blocks the most incident light on an otherwise opaque-electrode cell?","options":["Thin finger contacts","Transparent conductive oxide","Full metal top electrode","Sparse metal grid"],"answer":2,"explain":"整面不透明金屬上電極會大量遮光，因此一般使用細柵線或透明導電層。","source":"45","sourceKind":"review","pages":[45],"model":"Full metal top electrode"},{"id":"M108","type":"mc","chapter":9,"difficulty":3,"question":"An anti-reflection coating usually increases Jsc by...","options":["increasing photons entering the absorber","increasing the metal work function","making bandgap zero","creating electrons in darkness"],"answer":0,"explain":"ARC 減少反射，使更多光子進入吸收層，因此一般可提升 Jsc。","source":"32,44","sourceKind":"review","pages":[32,44],"model":"increasing photons entering the absorber"},{"id":"M109","type":"mc","chapter":9,"difficulty":3,"question":"Which is an optical loss rather than a recombination loss?","options":["Front reflection","SRH trap capture","Auger process","Radiative recombination"],"answer":0,"explain":"Reflection 使光子未被吸收，是光學損失；其他為載子復合機制。","source":"41,44","sourceKind":"review","pages":[41,44],"model":"Front reflection"},{"id":"M110","type":"mc","chapter":10,"difficulty":1,"question":"What does the Shockley–Queisser limit describe?","options":["Maximum theoretical efficiency of an ideal single-junction cell","Maximum battery capacity","Maximum laser intensity","Czochralski growth speed"],"answer":0,"explain":"SQ 極限是理想單接面太陽能電池在特定光譜及假設下的效率上限。","source":"47","sourceKind":"review","pages":[47],"model":"Maximum theoretical efficiency of an ideal single-junction cell"},{"id":"M111","type":"mc","chapter":10,"difficulty":1,"question":"Who introduced the Shockley–Queisser limit?","options":["Newton and Young","Shockley and Queisser","Einstein and Becquerel","Fritts and Czochralski"],"answer":1,"explain":"1961 年 William Shockley 與 Hans-Joachim Queisser 提出單接面 detailed-balance 模型。","source":"47","sourceKind":"review","pages":[47],"model":"Shockley and Queisser"},{"id":"M112","type":"mc","chapter":10,"difficulty":1,"question":"In which year was the Shockley–Queisser concept introduced?","options":["1839","1883","1905","1961"],"answer":3,"explain":"SQ 理論由 Shockley 與 Queisser 在 1961 年發表。","source":"47","sourceKind":"review","pages":[47],"model":"1961"},{"id":"M113","type":"mc","chapter":10,"difficulty":1,"question":"What is the approximate one-sun AM1.5G SQ limit quoted in the review?","options":["10%","20%","33.7%","100%"],"answer":2,"explain":"講義第 47 頁明確標示 33.7%，為特定標準條件下的理想上限。","source":"47","sourceKind":"review","pages":[47],"model":"33.7%"},{"id":"M114","type":"mc","chapter":10,"difficulty":2,"question":"What is a major assumption behind the ideal SQ analysis?","options":["Only radiative recombination is considered as intrinsic recombination loss","All photons have identical energy","There is no bandgap","Carrier extraction requires fuel"],"answer":0,"explain":"理想 SQ 模型將復合限制在輻射復合（detailed balance），不考慮實際缺陷等非輻射損失。","source":"47","sourceKind":"review","pages":[47],"model":"Only radiative recombination is considered as intrinsic recombination loss"},{"id":"M115","type":"mc","chapter":10,"difficulty":2,"question":"What happens to photons with energy below Eg in a simple band-to-band absorption model?","options":["They always create carriers","They are not absorbed across the bandgap","They have infinite thermalization","They all produce two electrons"],"answer":1,"explain":"E<Eg 的光子無法完成帶間激發，是 transmission / sub-bandgap loss。","source":"48","sourceKind":"review","pages":[48],"model":"They are not absorbed across the bandgap"},{"id":"M116","type":"mc","chapter":10,"difficulty":2,"question":"What happens to photon energy far above Eg after absorption?","options":["All excess energy becomes voltage","Excess energy usually relaxes as heat","It reduces Eg to zero","It is always emitted as UV"],"answer":1,"explain":"高於 Eg 的多餘能量多經熱化散失，無法全部變成輸出電壓。","source":"48","sourceKind":"review","pages":[48],"model":"Excess energy usually relaxes as heat"},{"id":"M117","type":"mc","chapter":10,"difficulty":2,"question":"How does a lower bandgap generally change a single-junction cell?","options":["Usually absorbs fewer photons","Generally increases potential Jsc but lowers possible Voc","Always eliminates recombination","Guarantees a higher PCE"],"answer":1,"explain":"低 Eg 能吸收更多光子提高 Jsc，但電壓能力較低，且熱化損失較大。","source":"49","sourceKind":"review","pages":[49],"model":"Generally increases potential Jsc but lowers possible Voc"},{"id":"M118","type":"mc","chapter":10,"difficulty":2,"question":"How does a higher bandgap generally affect Jsc?","options":["Usually lowers it by losing more long-wavelength photons","Always doubles it","Makes it independent of light","Makes photon energy smaller"],"answer":0,"explain":"高能隙的截止波長較短，許多長波光無法吸收，因此 Jsc 可能減少。","source":"49","sourceKind":"review","pages":[49],"model":"Usually lowers it by losing more long-wavelength photons"},{"id":"M119","type":"mc","chapter":10,"difficulty":2,"question":"Why can an intermediate Eg maximize PCE?","options":["It balances current and voltage","It makes all photons identical","It removes all reflection","It turns into a battery"],"answer":0,"explain":"效率取決於最大輸出功率，需要 Jsc 與 Voc 之間取得最佳平衡。","source":"49-50","sourceKind":"review","pages":[49,50],"model":"It balances current and voltage"},{"id":"M120","type":"mc","chapter":10,"difficulty":2,"question":"What is the central idea of a tandem solar cell?","options":["Use multiple bandgaps to divide the solar spectrum","Use no photon absorption","Replace light with hydrogen","Put all carriers into one metal"],"answer":0,"explain":"Tandem 將不同能量光子交給不同能隙子電池，降低能量不匹配損失。","source":"51","sourceKind":"review","pages":[51],"model":"Use multiple bandgaps to divide the solar spectrum"},{"id":"M121","type":"mc","chapter":10,"difficulty":2,"question":"In a two-junction tandem cell, the top cell typically has...","options":["lower Eg than bottom","higher Eg than bottom","no Eg","no absorption"],"answer":1,"explain":"上層高 Eg 吸收高能光；下層低 Eg 吸收穿透的較低能量光。","source":"51","sourceKind":"review","pages":[51],"model":"higher Eg than bottom"},{"id":"M122","type":"mc","chapter":10,"difficulty":1,"question":"What theoretical two-junction efficiency is quoted in this review for AM1.5G without concentration?","options":["20%","33.7%","47%","90%"],"answer":2,"explain":"講義第 51 頁列出雙接面 tandem 約 47% 理論極限，與單接面的 33.7% 比較。","source":"51","sourceKind":"review","pages":[51],"model":"47%"},{"id":"M123","type":"mc","chapter":10,"difficulty":3,"question":"Why is a tandem cell not constrained by the single-junction SQ limit?","options":["Because it has a different multi-junction architecture","Because it violates conservation of energy","Because photons stop being quantized","Because it uses no electrodes"],"answer":0,"explain":"SQ 的 33.7% 是單接面的理想條件；串疊電池將光譜拆分，屬不同架構。","source":"47,51","sourceKind":"review","pages":[47,51],"model":"Because it has a different multi-junction architecture"},{"id":"M124","type":"mc","chapter":10,"difficulty":3,"question":"Which mechanism acts much faster in the lecture schematic?","options":["Thermalization (fs–ps)","Long-lived recombination (~µs)","Crystal ingot pulling (~48 h)","Electrode screen printing (~minutes)"],"answer":0,"explain":"講義圖示熱化約 fs–ps，而所舉的復合時間尺度約 µs，兩者不可混淆。","source":"48","sourceKind":"review","pages":[48],"model":"Thermalization (fs–ps)"},{"id":"M125","type":"mc","chapter":11,"difficulty":1,"question":"Which recombination releases a photon?","options":["Auger","SRH","Radiative","Surface trap-assisted only"],"answer":2,"explain":"Radiative recombination 的釋能形式為光子。","source":"53","sourceKind":"review","pages":[53],"model":"Radiative"},{"id":"M126","type":"mc","chapter":11,"difficulty":1,"question":"Which recombination involves a defect or trap energy level?","options":["Radiative","SRH","Auger","Thermal reflection"],"answer":1,"explain":"SRH 經能隙內 trap state 分步捕捉電子、電洞完成復合。","source":"53","sourceKind":"review","pages":[53],"model":"SRH"},{"id":"M127","type":"mc","chapter":11,"difficulty":1,"question":"Which recombination gives its released energy to a third carrier?","options":["Auger","Radiative","Optical reflection","Photon transmission"],"answer":0,"explain":"Auger 復合將電子電洞復合的能量轉給第三個電子或電洞。","source":"53","sourceKind":"review","pages":[53],"model":"Auger"},{"id":"M128","type":"mc","chapter":11,"difficulty":2,"question":"Which recombination is especially important at high carrier injection or heavy doping?","options":["Auger","Diffraction","Transmission","Only reflection"],"answer":0,"explain":"Auger 涉及三載子，通常在高載子密度或重摻雜下更重要。","source":"53","sourceKind":"review","pages":[53],"model":"Auger"},{"id":"M129","type":"mc","chapter":11,"difficulty":2,"question":"What does SRH stand for?","options":["Shockley–Read–Hall","Silicon Radiation Heating","Single Radiative Hole","Surface Reflectance Histogram"],"answer":0,"explain":"SRH 即 Shockley–Read–Hall，經由缺陷能階的非輻射復合模型。","source":"53","sourceKind":"review","pages":[53],"model":"Shockley–Read–Hall"},{"id":"M130","type":"mc","chapter":11,"difficulty":2,"question":"Which material is known for strong radiative recombination due to a direct bandgap?","options":["GaAs","Typical crystalline Si","Glass","Metallic Al"],"answer":0,"explain":"GaAs 直接能隙，輻射復合較有效；矽是間接能隙，輻射復合相對弱。","source":"53","sourceKind":"review","pages":[53],"model":"GaAs"},{"id":"M131","type":"mc","chapter":11,"difficulty":2,"question":"Why is radiative recombination relatively weak in crystalline Si?","options":["Si is an indirect-bandgap semiconductor","Si has no valence band","Si is always an insulator","Si has infinite Eg"],"answer":0,"explain":"矽為間接能隙，帶間輻射復合需要滿足動量守恆，效率較低。","source":"53","sourceKind":"review","pages":[53],"model":"Si is an indirect-bandgap semiconductor"},{"id":"M132","type":"mc","chapter":11,"difficulty":2,"question":"What happens to the third carrier after an Auger event?","options":["It is always annihilated","It becomes energetic and later cools by phonon scattering","It becomes a permanent photon","It stops having charge"],"answer":1,"explain":"第三個載子只是拿到能量成為 hot carrier，最後通常透過聲子散射失去能量。","source":"53 延伸","sourceKind":"extension","sourceNote":"對應講義主題的延伸觀念；細節不一定逐字出現在講義。","pages":[53],"model":"It becomes energetic and later cools by phonon scattering"},{"id":"M133","type":"mc","chapter":11,"difficulty":3,"question":"Which rate dependence is characteristic of Auger recombination at high-level injection where n≈p?","options":["Approximately linear","Approximately quadratic","Approximately cubic","Independent of carrier density"],"answer":2,"explain":"高注入 n≈p 時，R_Auger∝n³；但一般重摻雜低注入條件的比例關係須分別分析。","source":"53 延伸","sourceKind":"extension","sourceNote":"對應講義主題的延伸觀念；細節不一定逐字出現在講義。","pages":[53],"model":"Approximately cubic"},{"id":"M134","type":"mc","chapter":11,"difficulty":3,"question":"If high-injection carrier density doubles, a cubic Auger rate increases about...","options":["2×","4×","8×","16×"],"answer":2,"explain":"R∝n³，濃度增加 2 倍會讓復合率約增加 2³=8 倍。","source":"53 延伸","sourceKind":"extension","sourceNote":"對應講義主題的延伸觀念；細節不一定逐字出現在講義。","pages":[53],"model":"8×"},{"id":"M135","type":"mc","chapter":11,"difficulty":3,"question":"How does stronger nonradiative recombination generally affect solar-cell Voc?","options":["Usually reduces Voc","Always increases Voc","Always makes Voc exactly Eg/q","Never affects Voc"],"answer":0,"explain":"非輻射復合加強通常增加損失，降低準費米能階分裂與 Voc。","source":"53 延伸","sourceKind":"extension","sourceNote":"對應講義主題的延伸觀念；細節不一定逐字出現在講義。","pages":[53],"model":"Usually reduces Voc"},{"id":"M136","type":"mc","chapter":12,"difficulty":1,"question":"Which statement about ITO is true?","options":["ITO is opaque pure metal","ITO is a transparent conducting oxide","ITO has no possible optical uses","ITO is always a p–n junction itself"],"answer":1,"explain":"ITO 是氧化銦錫，常用透明導電電極，原期中考第 6 題。","source":"歷屆Q6","sourceKind":"past-exam","sourceNote":"此題源自你提供的歷屆考卷或延伸史實；53 頁統整講義未直接收錄該資訊。","pages":[],"model":"ITO is a transparent conducting oxide"},{"id":"M137","type":"mc","chapter":12,"difficulty":2,"question":"A metal with Φ=3 eV is illuminated by a 413-nm photon. It is...","options":["approximately at threshold","far below threshold","always impossible at any intensity","a bandgap measurement"],"answer":0,"explain":"413 nm 約 3.00 eV，接近金屬功函數門檻。","source":"歷屆Q2","sourceKind":"past-exam","sourceNote":"此題源自你提供的歷屆考卷或延伸史實；53 頁統整講義未直接收錄該資訊。","pages":[],"model":"approximately at threshold"},{"id":"M138","type":"mc","chapter":12,"difficulty":2,"question":"A thin-film cell produces Jsc = 22.5 mA/cm², Voc = 1.05 V, FF = 0.75. Its PCE is...","options":["12.5%","17.72%","23.63%","75%"],"answer":1,"explain":"在 Pin=100 mW/cm² 時，PCE(%)=22.5×1.05×0.75=17.71875%。","source":"歷屆Q10","sourceKind":"past-exam","sourceNote":"此題源自你提供的歷屆考卷或延伸史實；53 頁統整講義未直接收錄該資訊。","pages":[],"model":"17.72%"},{"id":"M139","type":"mc","chapter":12,"difficulty":3,"question":"Which best distinguishes external photoelectric and photovoltaic effects?","options":["Both require electron emission to vacuum","Photoelectric: emission from surface; photovoltaic: internal charge separation and voltage","Photovoltaic always means hot water","Photoelectric effect needs a p–n junction"],"answer":1,"explain":"外部光電效應強調逸出真空，光伏效應強調材料內光生載子的分離收集。","source":"歷屆Q7","sourceKind":"past-exam","sourceNote":"此題源自你提供的歷屆考卷或延伸史實；53 頁統整講義未直接收錄該資訊。","pages":[],"model":"Photoelectric: emission from surface; photovoltaic: internal charge separation and voltage"},{"id":"M140","type":"mc","chapter":12,"difficulty":3,"question":"Which property is NOT a primary reason for high optical transmission in ITO?","options":["Wide optical gap","Appropriate thin-film optical properties","Free-carrier absorption can occur in infrared","It is perfectly opaque in visible light"],"answer":3,"explain":"ITO 在可見光通常具有高透過率；「可見光完全不透明」與性質矛盾。","source":"歷屆Q6","sourceKind":"past-exam","sourceNote":"此題源自你提供的歷屆考卷或延伸史實；53 頁統整講義未直接收錄該資訊。","pages":[],"model":"It is perfectly opaque in visible light"},{"id":"S001","type":"short","chapter":1,"difficulty":1,"question":"Compare a solar cell, a fuel cell, and a lithium battery.","model":"A solar cell converts sunlight into electricity. A fuel cell produces electricity from a continuous supply of fuel and oxygen. A lithium battery stores chemical energy and releases it when needed.","explain":"太陽能電池是光能轉電能；燃料電池持續消耗反應物產電；鋰電池先儲能再放電。重點在輸入與工作模式不同。","keywords":["sunlight","fuel","stores"],"source":"2","sourceKind":"review","pages":[2]},{"id":"S002","type":"short","chapter":1,"difficulty":2,"question":"Describe the three ways of harvesting sunlight shown in the lecture.","model":"Sunlight can be used for direct heating, heating water with solar collectors, or generating electricity through the photovoltaic effect.","explain":"講義列出光變熱、太陽集熱器供熱水、光伏效應發電三條路徑；本課重點是第三者。","keywords":["heating","water","photovoltaic"],"source":"1","sourceKind":"review","pages":[1]},{"id":"S003","type":"short","chapter":1,"difficulty":2,"question":"Why does a normal solar cell stop producing photovoltaic power in darkness?","model":"A solar cell needs incoming photons to generate electron-hole pairs. In darkness, new photogenerated carriers are absent, so the device cannot continuously supply photovoltaic power.","explain":"一般太陽能電池不是儲能裝置；沒有入射光便無法持續供應光生電力，與電池不同。","keywords":["photons","electron-hole","dark"],"source":"2","sourceKind":"review","pages":[2]},{"id":"S004","type":"short","chapter":2,"difficulty":3,"question":"What observations support the wave nature of light?","model":"Interference and diffraction support the wave nature of light. Thomas Young demonstrated interference, while Newton favored a particle picture of light.","explain":"Thomas Young 與干涉、繞射；Newton 與微粒說。記得概念和科學家配對。","keywords":["interference","diffraction","Young"],"source":"4","sourceKind":"review","pages":[4]},{"id":"S005","type":"short","chapter":2,"difficulty":1,"question":"What is a photon, and what determines its energy?","model":"A photon is a packet of light energy. Its energy is E = hν = hc/λ. A higher frequency or shorter wavelength gives a higher photon energy.","explain":"每一顆光子的能量取決於頻率／波長，不是光有多亮；可直接列出 E=hν=hc/λ。","keywords":["photon","frequency","wavelength"],"source":"5,10","sourceKind":"review","pages":[5,10]},{"id":"S006","type":"short","chapter":2,"difficulty":2,"question":"State the contributions of Einstein and Shockley–Queisser to solar-cell physics.","model":"Einstein explained the photoelectric effect using light quanta. Shockley and Queisser described the ideal single-junction solar-cell efficiency limit in 1961.","explain":"Einstein 對應光電效應量子解釋；Shockley 與 Queisser 對應 1961 年單接面效率理論上限。","keywords":["Einstein","photoelectric","1961"],"source":"5-6,47","sourceKind":"review","pages":[5,6,47]},{"id":"S007","type":"short","chapter":3,"difficulty":2,"question":"Explain the difference between the photoelectric effect and the photovoltaic effect.","model":"In the external photoelectric effect, a photon can eject an electron from a material if its energy is high enough. In the photovoltaic effect, light creates electron-hole pairs inside a semiconductor. Charge separation produces a voltage and useful current.","explain":"外部光電效應：電子離開表面且須克服功函數。光伏效應：材料內產生並分離電子電洞，不需要逸出真空。","keywords":["eject","electron-hole","voltage"],"source":"7-8","sourceKind":"review","pages":[7,8]},{"id":"S008","type":"short","chapter":3,"difficulty":3,"question":"Why can intense visible light fail to discharge a zinc plate?","model":"The energy of each photon depends on its frequency, not the light intensity. If the photon energy is below the work function, increasing brightness adds photons but does not eject electrons.","explain":"照度決定光子數量，波長決定單顆能量；超過金屬功函數是逸出必要條件。","keywords":["energy","intensity","work function"],"source":"11-14","sourceKind":"review","pages":[11,12,13,14]},{"id":"S009","type":"short","chapter":3,"difficulty":1,"question":"Define the work function and write the maximum kinetic-energy equation.","model":"The work function Φ is the minimum energy needed to remove an electron from the material to vacuum. The maximum kinetic energy of an emitted electron is Kmax = hν − Φ.","explain":"功函數是材料到真空能階的最低逸出能；入射光子能量扣除功函數，剩下是最大動能。","keywords":["minimum energy","vacuum","hν"],"source":"8","sourceKind":"review","pages":[8]},{"id":"S010","type":"short","chapter":3,"difficulty":2,"question":"Explain how photon energy changes with wavelength and intensity.","model":"Photon energy is inversely proportional to wavelength: E = hc/λ. Shorter wavelengths give more energy per photon. Higher intensity at the same wavelength mainly increases the number of photons.","explain":"波長減半 E 加倍；固定波長的照度提高只會改變每秒光子數（在單色光下）。","keywords":["inversely","shorter","number"],"source":"10,12","sourceKind":"review","pages":[10,12]},{"id":"S011","type":"short","chapter":4,"difficulty":2,"question":"What is a semiconductor bandgap and why is it important for light absorption?","model":"The bandgap Eg is the energy difference between the valence and conduction bands. A photon generally needs energy at least equal to Eg to excite an electron across the gap.","explain":"Eg 定義是 VB 頂到 CB 底差。吸收截止 λg≈1240/Eg；簡化為 E≥Eg 才能帶間激發。","keywords":["valence","conduction","Eg"],"source":"16-17","sourceKind":"review","pages":[16,17]},{"id":"S012","type":"short","chapter":4,"difficulty":3,"question":"Explain how phosphorus and boron change silicon conductivity.","model":"Phosphorus is a donor with five valence electrons. It makes n-type silicon with electrons as majority carriers. Boron is an acceptor with three valence electrons and makes p-type silicon with holes as majority carriers.","explain":"P→donor→N→electron；B→acceptor→P→hole。兩邊的多數載子不能寫反。","keywords":["donor","n-type","acceptor","p-type"],"source":"20","sourceKind":"review","pages":[20]},{"id":"S013","type":"short","chapter":4,"difficulty":1,"question":"Distinguish a bandgap from a metal work function.","model":"The bandgap is the energy difference between the valence and conduction bands. The work function is the minimum energy needed to move an electron from a solid to vacuum. They describe different energy thresholds.","explain":"Eg 是半導體能帶間距；Φ 是電子從材料到真空的最低能量。不要把兩者視為同一個物理量。","keywords":["bandgap","work function","vacuum"],"source":"8,16","sourceKind":"review","pages":[8,16]},{"id":"S014","type":"short","chapter":5,"difficulty":2,"question":"Describe the formation of a p–n junction and depletion region.","model":"Electrons diffuse from the n-side to the p-side, while holes diffuse from p to n. They recombine near the junction and leave fixed ions. The ions form a depletion region and a built-in electric field.","explain":"形成順序：擴散→復合→固定 donor/acceptor 離子→空乏區與內建電場。適合直接背。","keywords":["diffuse","recombine","fixed ions","field"],"source":"25-26","sourceKind":"review","pages":[25,26]},{"id":"S015","type":"short","chapter":5,"difficulty":2,"question":"Why is the depletion region important in a solar cell?","model":"The depletion region contains fixed charged ions that create a built-in electric field. The field helps separate photogenerated electrons and holes and reduces their chance of recombination.","explain":"空乏區不是完全沒有任何載子，而是自由載子濃度低。其內建場有助分離與收集光生載子。","keywords":["built-in electric field","separate","recombination"],"source":"26,28","sourceKind":"review","pages":[26,28]},{"id":"S016","type":"short","chapter":5,"difficulty":3,"question":"What are the directions of electron and hole movement in the built-in field?","model":"At a typical p–n junction, the built-in electric field points from the n-side to the p-side. Electrons drift toward the n-side, while holes drift toward the p-side.","explain":"電場由正 donor（N 側）指向負 acceptor（P 側）；電子受力與電場相反，電洞同向。","keywords":["n-side","p-side","electrons","holes"],"source":"26","sourceKind":"review","pages":[26]},{"id":"S017","type":"short","chapter":5,"difficulty":1,"question":"What is the difference between diffusion current and drift current?","model":"Diffusion current is caused by a carrier concentration gradient. Drift current is caused by an electric field. At equilibrium in a p–n junction, the two current contributions balance.","explain":"擴散的驅動力是濃度梯度；漂移是電場；平衡時淨電流為零。本題後半屬講義觀念延伸。","keywords":["concentration","electric field","balance"],"source":"25-26 延伸","sourceKind":"extension","sourceNote":"概念取自對應講義頁面，部分細節為延伸。","pages":[25,26]},{"id":"S018","type":"short","chapter":6,"difficulty":2,"question":"Describe the Czochralski method for producing silicon wafers.","model":"A single-crystal silicon seed touches molten silicon. The seed is slowly pulled and rotated to grow a crystal ingot. The ingot is then sliced into silicon wafers.","explain":"講義第30頁：seed 接觸熔融 Si、旋轉慢拉、長單晶柱、切片。Seed 決定晶向。","keywords":["seed","molten","pulled","wafers"],"source":"30","sourceKind":"review","pages":[30]},{"id":"S019","type":"short","chapter":6,"difficulty":2,"question":"Why is surface texturing used in silicon solar cells?","model":"Surface texturing reduces the reflection of incoming sunlight. It increases the amount of light entering the absorber and can increase the short-circuit current.","explain":"表面金字塔紋理讓光多次反射，降低前表面反射；可以提升吸收與 Jsc。","keywords":["texturing","reflection","light"],"source":"32","sourceKind":"review","pages":[32]},{"id":"S020","type":"short","chapter":6,"difficulty":3,"question":"What is the purpose of the anti-reflection coating (ARC)?","model":"An anti-reflection coating reduces reflection at the front surface. More sunlight enters the silicon absorber, helping increase photocurrent.","explain":"講義第32頁：SiNx 抗反射層，減少前表面反射；在實際製程中也可有鈍化作用，但本講義聚焦抗反射。","keywords":["coating","reflection","photocurrent"],"source":"31-32","sourceKind":"review","pages":[31,32]},{"id":"S021","type":"short","chapter":6,"difficulty":1,"question":"Why is phosphorus diffusion used when making a silicon solar cell?","model":"Phosphorus diffusion introduces donor atoms into silicon to form an n-type region. Together with a p-type region, it creates the p–n junction needed for carrier separation.","explain":"P 擴散可形成 N 型射極與 P 型基底的 PN 接面。講義第31頁流程對應。","keywords":["phosphorus","n-type","p-n junction"],"source":"31","sourceKind":"review","pages":[31]},{"id":"S022","type":"short","chapter":6,"difficulty":2,"question":"What are PSG removal and contact firing in silicon-cell production?","model":"PSG removal removes the phosphosilicate glass formed during phosphorus diffusion. Contact firing heats printed electrodes to form electrical contacts through the SiNx coating.","explain":"PSG 是磷擴散後表面的磷矽酸鹽玻璃；第31頁說明 Step 4–5 去 PSG、Step 8 firing 形成接觸。","keywords":["PSG","remove","firing","contacts"],"source":"31","sourceKind":"review","pages":[31]},{"id":"S023","type":"short","chapter":7,"difficulty":2,"question":"Define open-circuit voltage and short-circuit current.","model":"Voc is the terminal voltage when the external current is zero. Isc is the current when the terminal voltage is zero. Both are key points on the solar-cell current–voltage curve.","explain":"Open circuit：I=0、V=Voc；Short circuit：V=0、I=Isc。最常見混淆。","keywords":["voltage","zero current","zero voltage","current"],"source":"34-35","sourceKind":"review","pages":[34,35]},{"id":"S024","type":"short","chapter":7,"difficulty":3,"question":"What is the maximum power point (MPP)?","model":"The maximum power point is the operating point where the solar cell delivers the greatest product of current and voltage. It is found on the illuminated I–V curve under an appropriate load.","explain":"P=IV，最大功率點的 I 與 V 不等於 Isc 或 Voc；負載決定工作點。","keywords":["maximum","current","voltage","load"],"source":"36","sourceKind":"review","pages":[36]},{"id":"S025","type":"short","chapter":7,"difficulty":1,"question":"Define fill factor (FF) and explain its effect on solar-cell efficiency.","model":"The fill factor compares the maximum output power to Voc × Isc. FF = Pmax/(Voc × Isc). A larger FF generally gives a higher conversion efficiency when the other parameters stay fixed.","explain":"FF 是 J–V 曲線矩形度，式子可改用 JmVm/(JscVoc)。FF 越高在其他條件固定下 PCE 越高。","keywords":["maximum power","Voc","Isc","efficiency"],"source":"36-37","sourceKind":"review","pages":[36,37]},{"id":"S026","type":"short","chapter":7,"difficulty":2,"question":"Write the power-conversion efficiency equation and identify all terms.","model":"PCE = (Voc × Jsc × FF / Pin) × 100%. Voc is open-circuit voltage, Jsc is short-circuit current density, FF is fill factor, and Pin is incident light power density.","explain":"使用單位 V、mA/cm²、mW/cm² 會互相抵消；Pin=100 時 PCE(%) 數值等於 Voc×Jsc×FF。","keywords":["Voc","Jsc","FF","Pin"],"source":"37","sourceKind":"review","pages":[37]},{"id":"S027","type":"short","chapter":8,"difficulty":2,"question":"What is the difference between EQE and IQE?","model":"EQE is the number of collected electrons divided by the number of incident photons. IQE uses the number of absorbed photons instead. Therefore, IQE is normally greater than or equal to EQE.","explain":"兩者分子相同，分母不同：入射光子 vs 被吸收光子。講義給 IQE=EQE/(1−R−T)。","keywords":["incident","absorbed","collected"],"source":"40","sourceKind":"review","pages":[40]},{"id":"S028","type":"short","chapter":8,"difficulty":3,"question":"Explain why EQE may be lower than IQE.","model":"Some incident photons are reflected, transmitted, or blocked before generating collected carriers. EQE includes these optical losses, while IQE counts only absorbed photons in its denominator.","explain":"遮光、反射、穿透會讓外量子效率降低。此處使用講義的簡化吸收定義。","keywords":["reflected","transmitted","incident"],"source":"40-41","sourceKind":"review","pages":[40,41]},{"id":"S029","type":"short","chapter":8,"difficulty":1,"question":"What does EQE measure in a solar-cell experiment?","model":"External quantum efficiency measures the fraction of incident photons that produce collected charge carriers. It indicates the wavelength-dependent photoresponse of the cell.","explain":"EQE 是外部入射光子的收集比例，需注意 wavelength-dependent；不同波長之 EQE 可找出光學與收集損失。","keywords":["incident photons","collected","wavelength"],"source":"39-41","sourceKind":"review","pages":[39,40,41]},{"id":"S030","type":"short","chapter":9,"difficulty":2,"question":"Why are thin metal fingers used instead of a full metal top electrode?","model":"Metal contacts collect charges, but they also block incoming light. Thin fingers reduce shading while still providing a path for current collection.","explain":"整面不透明金屬會擋光；細柵線降低遮光，仍能導出載子，是導電與透光間折衷。","keywords":["collect","block light","thin fingers"],"source":"45","sourceKind":"review","pages":[45]},{"id":"S031","type":"short","chapter":9,"difficulty":2,"question":"Explain blue loss in the EQE spectrum of silicon solar cells.","model":"Short-wavelength blue photons are absorbed close to the front surface. Some generated carriers recombine at surface defects before collection, reducing the blue-region EQE.","explain":"短波在表面附近吸收，表面缺陷復合顯著，因此 EQE 短波段掉下來。","keywords":["short wavelength","surface","recombine"],"source":"44","sourceKind":"review","pages":[44]},{"id":"S032","type":"short","chapter":9,"difficulty":3,"question":"What losses are common at long wavelengths in silicon solar cells?","model":"Long-wavelength photons are absorbed weakly or deeper in the cell. Some pass through the absorber, and some generated carriers are lost during collection in the base.","explain":"長波在深處生成或未被吸收，可能有 base collection loss、寄生吸收、透射損失。","keywords":["long wavelength","absorption","collection"],"source":"44","sourceKind":"review","pages":[44]},{"id":"S033","type":"short","chapter":10,"difficulty":1,"question":"What is the Shockley–Queisser limit?","model":"The Shockley–Queisser limit is the maximum theoretical efficiency of an ideal single-junction solar cell. Under one-sun AM1.5G light, the lecture quotes about 33.7%.","explain":"SQ 極限針對理想單接面、AM1.5G one sun 約 33.7%；理論由兩位學者於 1961 年提出。","keywords":["single-junction","theoretical","33.7"],"source":"47","sourceKind":"review","pages":[47]},{"id":"S034","type":"short","chapter":10,"difficulty":2,"question":"Why can the efficiency of a single-junction cell not reach 100%?","model":"Photons below the bandgap are not absorbed, and excess energy from photons above the bandgap is lost as heat. Radiative recombination also limits the output voltage.","explain":"兩大光譜損失：E<Eg 不吸收；E>Eg 多餘熱化。理想條件仍有 radiative recombination。","keywords":["below bandgap","heat","radiative"],"source":"47-48","sourceKind":"review","pages":[47,48]},{"id":"S035","type":"short","chapter":10,"difficulty":2,"question":"Explain the trade-off between low and high bandgap solar cells.","model":"A low bandgap absorbs more photons and can produce a higher current, but has lower possible voltage. A high bandgap can give higher voltage but absorbs fewer photons. An intermediate bandgap balances both.","explain":"低 Eg 高 Jsc 低 Voc、多餘能量熱化；高 Eg 高 Voc 低 Jsc、更多光子穿透；中間 Eg 有最佳折衷。","keywords":["low bandgap","current","high bandgap","voltage"],"source":"49-50","sourceKind":"review","pages":[49,50]},{"id":"S036","type":"short","chapter":10,"difficulty":3,"question":"How does a tandem solar cell reduce energy losses?","model":"A tandem cell stacks absorbers with different bandgaps. The high-bandgap top cell absorbs high-energy photons, while the low-bandgap bottom cell absorbs lower-energy photons. This reduces thermalization and transmission losses.","explain":"高 Eg 上層與低 Eg 下層分工吸收光譜，突破「單接面」SQ 限制；講義雙接面近 47%。","keywords":["high-bandgap","top","low-bandgap","bottom"],"source":"51","sourceKind":"review","pages":[51]},{"id":"S037","type":"short","chapter":10,"difficulty":1,"question":"What is thermalization loss in a solar cell?","model":"When a photon has energy above Eg, the excited carrier quickly relaxes toward a band edge. The excess energy is transferred to the lattice as heat and cannot be fully used as electrical output.","explain":"光子 E>Eg 的多餘能量經快速載子冷卻散失，講義示意為 fs–ps 尺度。","keywords":["above Eg","relaxes","heat"],"source":"48","sourceKind":"review","pages":[48]},{"id":"S038","type":"short","chapter":11,"difficulty":2,"question":"Compare radiative, SRH, and Auger recombination.","model":"Radiative recombination emits a photon. SRH recombination occurs through defect or trap states. Auger recombination transfers energy to a third carrier instead of emitting light.","explain":"三者最好背能量去向：光子、陷阱、第三載子。Q5 最可能比較 Auger 的重摻雜條件。","keywords":["photon","trap","third carrier"],"source":"53","sourceKind":"review","pages":[53]},{"id":"S039","type":"short","chapter":11,"difficulty":2,"question":"Why is Auger recombination important under heavy doping?","model":"Auger recombination involves three carriers. At high carrier concentrations, these three-carrier interactions become more likely and reduce carrier lifetime.","explain":"Auger 是三載子相關的非輻射復合，濃度越高通常越明顯；重摻雜或高注入條件很重要。","keywords":["three carriers","high concentration","lifetime"],"source":"53","sourceKind":"review","pages":[53]},{"id":"S040","type":"short","chapter":11,"difficulty":3,"question":"Explain SRH recombination and its relationship to defects.","model":"SRH recombination takes place through trap energy levels inside the bandgap. Crystal defects and impurities create these traps, allowing electrons and holes to recombine in steps.","explain":"陷阱能階位於能隙內，電子電洞分步捕獲，常與材料缺陷及雜質有關。","keywords":["trap","bandgap","defects"],"source":"53","sourceKind":"review","pages":[53]},{"id":"S041","type":"short","chapter":11,"difficulty":1,"question":"Why is radiative recombination relatively weak in silicon?","model":"Silicon has an indirect bandgap, so photon-emitting electron-hole recombination is less probable than in direct-bandgap materials such as GaAs.","explain":"Si 是間接能隙，單純輻射復合較不利；GaAs 等直接能隙半導體更常見高輻射效率。","keywords":["indirect","silicon","GaAs"],"source":"53","sourceKind":"review","pages":[53]},{"id":"S042","type":"short","chapter":12,"difficulty":2,"question":"State two differences between an ideal solar cell and a real solar cell.","model":"An ideal cell neglects many nonradiative and optical losses. A real cell experiences reflection, electrode shading, carrier recombination, and resistance losses. These effects lower the practical efficiency.","explain":"整合題：SQ 模型理想化；實際太陽能電池還有反射、遮光、缺陷復合等損失。屬跨頁綜合。","keywords":["ideal","reflection","recombination"],"source":"32,44-45,47,53","sourceKind":"review","pages":[32,44,45,47,53]},{"id":"S043","type":"short","chapter":12,"difficulty":2,"question":"Describe what happens in an illuminated solar cell under open-circuit and short-circuit conditions.","model":"At open circuit, no external current flows and the terminal voltage reaches Voc. At short circuit, the terminal voltage is zero and photocurrent can flow through the external wire.","explain":"開路時 I=0 且 V=Voc；短路時 V=0 且 I=Isc。講義第34–35頁圖表配對。","keywords":["open circuit","zero current","short circuit","zero voltage"],"source":"34-35","sourceKind":"review","pages":[34,35]},{"id":"C001","type":"calc","chapter":3,"difficulty":1,"question":"A photon has wavelength 620 nm. Calculate its energy in eV.","answer":2.0,"unit":"eV","tolerance":0.02,"explain":"短波長高能量；公式 E(eV)=1240/λ(nm)。","model":"E=1240/620=2.00 eV.","source":"10","sourceKind":"review","pages":[10]},{"id":"C002","type":"calc","chapter":3,"difficulty":2,"question":"Find the wavelength of a photon with energy 2.5 eV.","answer":496.0,"unit":"nm","tolerance":1.0,"explain":"λ=1240/E。","model":"λ=1240/2.5=496 nm.","source":"10","sourceKind":"review","pages":[10]},{"id":"C003","type":"calc","chapter":3,"difficulty":3,"question":"A metal has work function 3.0 eV. Find its threshold wavelength.","answer":413.33,"unit":"nm","tolerance":1.0,"explain":"光電子逸出所需 E≥Φ；臨界波長最大值。","model":"λmax=1240/3.0≈413.33 nm.","source":"8-10","sourceKind":"review","pages":[8,9,10]},{"id":"C004","type":"calc","chapter":3,"difficulty":1,"question":"Light of wavelength 310 nm hits a metal with Φ = 3.0 eV. Find the maximum kinetic energy of emitted electrons.","answer":1.0,"unit":"eV","tolerance":0.02,"explain":"光子 4.0 eV，扣除功函數 3.0 eV。","model":"E=1240/310=4.0 eV; Kmax=4.0−3.0=1.0 eV.","source":"8,10","sourceKind":"review","pages":[8,10]},{"id":"C005","type":"calc","chapter":3,"difficulty":2,"question":"What is the photon energy at 400 nm?","answer":3.1,"unit":"eV","tolerance":0.02,"explain":"紫光／近紫外光每光子能量大於紅外光。","model":"E=1240/400=3.10 eV.","source":"10","sourceKind":"review","pages":[10]},{"id":"C006","type":"calc","chapter":3,"difficulty":3,"question":"A photon energy is 1.5 eV. Calculate its wavelength.","answer":826.67,"unit":"nm","tolerance":2.0,"explain":"此值與講義例題 826.5 nm 一致（常數取近似）。","model":"λ=1240/1.5≈826.67 nm.","source":"10,17","sourceKind":"review","pages":[10,17]},{"id":"C007","type":"calc","chapter":3,"difficulty":1,"question":"A 500-nm photon strikes a metal with Φ = 2.0 eV. Find Kmax.","answer":0.48,"unit":"eV","tolerance":0.02,"explain":"光子能量 2.48 eV，剛好比功函數高 0.48 eV。","model":"E=1240/500=2.48 eV; Kmax=2.48−2.00=0.48 eV.","source":"8-10","sourceKind":"review","pages":[8,9,10]},{"id":"C008","type":"calc","chapter":3,"difficulty":2,"question":"A 700-nm photon strikes a metal with Φ = 2.0 eV. How much is the photon energy in eV?","answer":1.7714,"unit":"eV","tolerance":0.02,"explain":"E小於Φ，故單光子外部光電效應無逸出；但本題僅求光子能量。","model":"E=1240/700≈1.77 eV < 2.00 eV.","source":"8-10","sourceKind":"review","pages":[8,9,10]},{"id":"C009","type":"calc","chapter":4,"difficulty":3,"question":"Find the longest wavelength able to excite a semiconductor with Eg = 2.0 eV.","answer":620.0,"unit":"nm","tolerance":2.0,"explain":"截止波長 λg=1240/Eg；波長更長一般無法帶間激發。","model":"λg=1240/2.0=620 nm.","source":"16-17","sourceKind":"review","pages":[16,17]},{"id":"C010","type":"calc","chapter":4,"difficulty":1,"question":"A semiconductor has Eg = 1.8 eV. Calculate the absorption-edge wavelength.","answer":688.89,"unit":"nm","tolerance":2.0,"explain":"材料能隙越大，截止波長越短。","model":"λg=1240/1.8≈688.89 nm.","source":"16-17","sourceKind":"review","pages":[16,17]},{"id":"C011","type":"calc","chapter":7,"difficulty":2,"question":"A solar cell has Jsc = 22.5 mA/cm², Voc = 1.05 V, FF = 0.75 and Pin=100 mW/cm². Find PCE in percent.","answer":17.71875,"unit":"%","tolerance":0.05,"explain":"歷屆題目原題。正確百分比為 17.72%。","model":"PCE=(22.5×1.05×0.75/100)×100%=17.71875%.","source":"37","sourceKind":"review","pages":[37]},{"id":"C012","type":"calc","chapter":7,"difficulty":3,"question":"A solar cell has Jsc = 20.09 mA/cm², Voc = 1.04 V and FF = 0.67. Calculate PCE (%) for Pin=100 mW/cm².","answer":14.000712,"unit":"%","tolerance":0.05,"explain":"講義第38頁 No725。","model":"PCE=20.09×1.04×0.67≈14.00%.","source":"38","sourceKind":"review","pages":[38]},{"id":"C013","type":"calc","chapter":7,"difficulty":1,"question":"A solar cell has Jsc = 24.88 mA/cm², FF = 0.75 and PCE = 18.40%. Find Voc in V.","answer":0.986066,"unit":"V","tolerance":0.01,"explain":"由 PCE(%)=Voc×Jsc×FF，倒推 Voc。","model":"Voc=18.40/(24.88×0.75)≈0.986 V.","source":"38","sourceKind":"review","pages":[38]},{"id":"C014","type":"calc","chapter":7,"difficulty":2,"question":"A device has Jsc = 22.64 mA/cm², Voc = 0.98 V and PCE=16.90%. Find FF.","answer":0.761653,"unit":"no unit","tolerance":0.02,"explain":"由 PCE 倒推 FF，注意 FF 不是百分比輸入。","model":"FF=16.90/(22.64×0.98)≈0.762.","source":"38","sourceKind":"review","pages":[38]},{"id":"C015","type":"calc","chapter":7,"difficulty":3,"question":"A device has Jsc=15.25 mA/cm², Voc=0.96 V, FF=0.60. Find PCE (%).","answer":8.784,"unit":"%","tolerance":0.05,"explain":"講義第38頁 No732；電流較低，所以效率也低。","model":"PCE=15.25×0.96×0.60=8.784%.","source":"38","sourceKind":"review","pages":[38]},{"id":"C016","type":"calc","chapter":7,"difficulty":1,"question":"A device has PCE = 4.29%, Voc=1.02 V and FF=0.67. Find Jsc in mA/cm².","answer":6.276559,"unit":"mA/cm²","tolerance":0.1,"explain":"講義第38頁 No734，求 Jsc 必須用 PCE(%) 數值除以 Voc×FF。","model":"Jsc=4.29/(1.02×0.67)≈6.28 mA/cm².","source":"38","sourceKind":"review","pages":[38]},{"id":"C017","type":"calc","chapter":7,"difficulty":2,"question":"A device has Jsc=24.04 mA/cm², FF=0.78 and PCE=18.81%. Calculate Voc.","answer":1.0031,"unit":"V","tolerance":0.01,"explain":"講義第38頁 No735。","model":"Voc=18.81/(24.04×0.78)≈1.003 V.","source":"38","sourceKind":"review","pages":[38]},{"id":"C018","type":"calc","chapter":7,"difficulty":3,"question":"A device has Jsc=22.98 mA/cm², Voc=1.03 V, FF=0.72. Calculate PCE (%).","answer":17.042,"unit":"%","tolerance":0.05,"explain":"講義第38頁 No736。","model":"PCE=22.98×1.03×0.72≈17.04%.","source":"38","sourceKind":"review","pages":[38]},{"id":"C019","type":"calc","chapter":7,"difficulty":1,"question":"A cell has Voc=1.0 V, Isc=20 mA, Vmpp=0.8 V and Impp=18 mA. Calculate FF.","answer":0.72,"unit":"no unit","tolerance":0.02,"explain":"FF=Pmax/(Voc×Isc)，電壓與電流單位使用一致即可。","model":"FF=(0.8×18)/(1.0×20)=0.72.","source":"36-37 延伸","sourceKind":"extension","sourceNote":"概念取自對應講義頁面，部分細節為延伸。","pages":[36,37]},{"id":"C020","type":"calc","chapter":7,"difficulty":2,"question":"A cell has Jsc = 25 mA/cm², Voc=1.0 V and FF=0.8. Find maximum output power density in mW/cm².","answer":20.0,"unit":"mW/cm²","tolerance":0.1,"explain":"最大輸出功率密度 = Voc×Jsc×FF。","model":"Pmax/A=25×1.0×0.8=20 mW/cm².","source":"37","sourceKind":"review","pages":[37]},{"id":"C021","type":"calc","chapter":8,"difficulty":3,"question":"A solar cell collects 85 electrons for every 100 incident photons. Find EQE in percent.","answer":85.0,"unit":"%","tolerance":0.1,"explain":"EQE=收集電子數/入射光子數。","model":"EQE=(85/100)×100%=85%.","source":"40","sourceKind":"review","pages":[40]},{"id":"C022","type":"calc","chapter":8,"difficulty":1,"question":"A cell has EQE=72%, reflectance R=10% and transmission T=10%. Find IQE (%).","answer":90.0,"unit":"%","tolerance":0.2,"explain":"A=1−R−T=80%；IQE=EQE/A。","model":"IQE=0.72/(1−0.10−0.10)=0.90=90%.","source":"40","sourceKind":"review","pages":[40]},{"id":"C023","type":"calc","chapter":8,"difficulty":2,"question":"At a wavelength, R=15% and T=5%. Find absorptance A in percent.","answer":80.0,"unit":"%","tolerance":0.1,"explain":"能量平衡 A+R+T=1。","model":"A=(1−0.15−0.05)×100%=80%.","source":"40","sourceKind":"review","pages":[40]},{"id":"C024","type":"calc","chapter":8,"difficulty":3,"question":"A device has EQE=60% and measured absorptance=75%. Calculate IQE (%).","answer":80.0,"unit":"%","tolerance":0.1,"explain":"講義定義 IQE=EQE/(1−R−T)；在同一波長使用百分比相除。","model":"IQE=60%/0.75=80%.","source":"40","sourceKind":"review","pages":[40]},{"id":"C025","type":"calc","chapter":10,"difficulty":1,"question":"Under a simplified model, a photon has energy 2.5 eV and Eg=1.5 eV. How much excess energy (in eV) is lost to thermalization?","answer":1.0,"unit":"eV","tolerance":0.01,"explain":"大於 Eg 的超額能量最終可藉載子熱化散失；簡化為 E−Eg。","model":"Excess=2.5−1.5=1.0 eV.","source":"48","sourceKind":"review","pages":[48]},{"id":"C026","type":"calc","chapter":10,"difficulty":2,"question":"What is the approximate efficiency advantage (in percentage points) of the 47% two-junction limit over the 33.7% single-junction limit in the review?","answer":13.3,"unit":"percentage points","tolerance":0.2,"explain":"需用百分點相減，而不是百分比相除。","model":"47.0−33.7=13.3 percentage points.","source":"47,51","sourceKind":"review","pages":[47,51]}]};
